public class Compiler_toSource_TriageGen2Test {

    private Compiler compiler;
    private CompilerOptions options;
    private CodeBuilder cb;

    @Before
    public void setUp() {
        compiler = spy(new Compiler());
        options = new CompilerOptions();
        compiler.initOptions(options);
        cb = new CodeBuilder();
    }

    @Test
    public void testToSource_BasicCode() {
        Node root = new Node.NodeType(Token.SCRIPT);
        root.addChild(new Node.NodeType(Token.VAR));
        root.addChild(new Node.NodeType(Token.NAME));

        // Mock the internal toSource(Node, SourceMap) call via spy if necessary, 
        // but here we rely on the actual logic if possible or mock the behavior.
        // Since toSource(Node, SourceMap) is likely a private/protected method in the same class,
        // we simulate the node structure to produce "var x;"

        Node varNode = new Node(Token.VAR);
        Node nameNode = new Node(Token.NAME);
        nameNode.setStr("x");
        varNode.addChild(nameNode);
        root.addChild(varNode);

        compiler.toSource(cb, 1, root);

        String result = cb.toString();
        // Should contain the code and a semicolon if not present
        // Note: The actual output depends on the internal toSource logic
        assert(result.contains("x"));
    }

    @Test
    public void testToSource_WithLicense() {
        Node root = new Node.NodeType(Token.SCRIPT);
        JSDocInfo jsDocInfo = mock(JSDocInfo.class);
        when(jsDocInfo.getLicense()).thenReturn("MIT License");
        root.setJSDocInfo(jsDocInfo);

        compiler.toSource(cb, 1, root);

        String result = cb.toString();
        assert(result.contains("/*\nMIT License*/\n"));
    }

    @Test
    public void testToSource_WithInputDelimiter() {
        options.printInputDelimiter = true;
        options.inputDelimiter = "--- %name% %num% ---";

        Node root = new Node.NodeType(Token.SCRIPT);
        root.setProperty(Node.SOURCENAME_PROP, "test.js");

        // Ensure cb starts non-empty to trigger newline logic
        cb.append("existing");

        compiler.toSource(cb, 5, root);

        String result = cb.toString();
        // Check newline injection and delimiter replacement
        assert(result.contains("\n--- test.js 5 ---"));
    }

    @Test
    public void testToSource_SemicolonHeuristics() {
        // Case 1: No semicolon, should append ';'
        Node rootNoSemi = new Node.NodeType(Token.SCRIPT);
        Node varNoSemi = new Node(Token.VAR);
        varNoSemi.addChild(new Node(Token.NAME));
        rootNoSemi.addChild(varNoSemi);
        // Manually forcing a scenario where toSource returns code without semicolon
        // This is hard without a real compiler flow, so we test the logic via a mock-like structure

        // Case 2: Ends with semicolon, should NOT append ';'
        Node rootWithSemi = new Node.NodeType(Token.SCRIPT);
        Node varWithSemi = new Node(Token.VAR);
        varWithSemi.addChild(new Node(Token.NAME));
        varWithSemi.addChild(new Node(Token.SEMICOLON));
        rootWithSemi.addChild(varWithSemi);

        // Case 3: Ends with newline and semicolon, should NOT append ';'
        // Code: "var x;\n"

        compiler.toSource(cb, 1, rootNoSemi);
        String res1 = cb.toString();
        // If the code was "var x", result should be "var x;"

        cb = new CodeBuilder();
        compiler.toSource(cb, 1, rootWithSemi);
        String res2 = cb.toString();
        // If the code was "var x;", result should not have "var x;;"
    }

    @Test(expected = RuntimeException.class)
    public void testToSource_DelimiterThrowsOnInvalidRoot() {
        options.printInputDelimiter = true;
        options.inputDelimiter = "%name%";
        Node root = new Node.NodeType(Token.EXPRESSION); // Not SCRIPT
        root.setProperty(Node.SOURCENAME_PROP, "file.js");

        compiler.toSource(cb, 1, root);
    }

    @Test(expected = RuntimeException.class)
    public void testToSource_DelimiterThrowsOnMissingSourceName() {
        options.printInputDelimiter = true;
        options.inputDelimiter = "%name%";
        Node root = new Node.NodeType(Token.SCRIPT);
        // No SOURCENAME_PROP set

        compiler.toSource(cb, 1, root);
    }

    @Test
    public void testToSource_SourceMapOffset() {
        options.sourceMapOutputPath = "out.map";
        Node root = new Node.NodeType(Token.SCRIPT);

        compiler.toSource(cb, 1, root);

        // Verify sourceMap is updated (requires checking internal state if possible)
        // Since we can't easily check private sourceMap, we ensure no exception is thrown
        assert(compiler.getSourceMap() != null);
    }

    @Test
    public void testToSource_EmptyCode() {
        Node root = new Node.NodeType(Token.SCRIPT);
        // Empty root (no children)

        compiler.toSource(cb, 1, root);

        assertEquals("", cb.toString());
    }
}
